sys_variable_value.value:
(function execute(inputs, outputs) {

    var studentId = inputs.student;

    // =========================================================
    // 1. INITIAL VARIABLES
    // =========================================================

    var interviewTotal = 0;
    var interviewCount = 0;

    var skillTotal = 0;
    var skillCount = 0;

    var assessmentTotal = 0;
    var assessmentCount = 0;

    var applicationTotal = 0;
    var applicationCount = 0;

    var trainingAttendanceTotal = 0;
    var trainingCompletionTotal = 0;
    var trainingCount = 0;

    var mockInterviewCount = 0;
    var completedInterviewCount = 0;

    var missedOpportunities = 0;


    // =========================================================
    // 2. INTERVIEW PERFORMANCE
    //    Uses ALL historical Interview Feedback records
    // =========================================================

    var feedbackGR = new GlideRecord(
        'x_snc_campus360_interview_feedback'
    );

    feedbackGR.addQuery('student', studentId);
    feedbackGR.query();

    while (feedbackGR.next()) {

        var overallScore = parseFloat(
            feedbackGR.getValue('overall_score')
        );

        if (!isNaN(overallScore)) {
            interviewTotal += overallScore;
            interviewCount++;
        }
    }


    // =========================================================
    // 3. SKILL READINESS
    //    Uses ALL Student Skills records
    // =========================================================

    var skillGR = new GlideRecord(
        'x_snc_campus360_student_skills'
    );

    skillGR.addQuery('student', studentId);
    skillGR.query();

    while (skillGR.next()) {

        var skillScore = parseFloat(
            skillGR.getValue('assessment_score')
        );

        if (!isNaN(skillScore)) {
            skillTotal += skillScore;
            skillCount++;
        }
    }


    // =========================================================
    // 4. ASSESSMENT PERFORMANCE
    //
    // Passed       = 100
    // Failed       = 0
    // In Progress  = 50
    // Scheduled    = 50
    // Not Started  = 0
    // =========================================================

    var assessmentGR = new GlideRecord(
        'x_snc_campus360_student_assessment'
    );

    assessmentGR.addQuery('student', studentId);
    assessmentGR.query();

    while (assessmentGR.next()) {

        var result = (
            assessmentGR.getValue('result') || ''
        ).toLowerCase();

        var assessmentScore = null;

        if (result == 'passed') {

            assessmentScore = 100;

        } else if (result == 'failed') {

            assessmentScore = 0;

        } else if (
            result == 'in_progress' ||
            result == 'in progress' ||
            result == 'scheduled'
        ) {

            assessmentScore = 50;

        } else if (
            result == 'not_started' ||
            result == 'not started'
        ) {

            assessmentScore = 0;

        }

        if (assessmentScore !== null) {
            assessmentTotal += assessmentScore;
            assessmentCount++;
        }
    }


    // =========================================================
    // 5. APPLICATION READINESS
    //
    // Offer Accepted       = 100
    // Selected              = 100
    // Interview Completed   = 90
    // Shortlisted           = 80
    // Assessment Passed     = 70
    // Assessment In Progress= 60
    // Submitted/Under Review= 50
    // Pending               = 40
    // Rejected              = 20
    // Withdrawn             = 10
    //
    // Missed Opportunities:
    // student_response = ignored OR not_interested
    // =========================================================

    var applicationGR = new GlideRecord(
        'x_snc_campus360_student_application'
    );

    applicationGR.addQuery('student', studentId);
    applicationGR.query();

    while (applicationGR.next()) {

        var applicationStatus = (
            applicationGR.getValue('application_status') || ''
        ).toLowerCase();

        var assessmentStatus = (
            applicationGR.getValue('assessment_status') || ''
        ).toLowerCase();

        var interviewStatus = (
            applicationGR.getValue('interview_status') || ''
        ).toLowerCase();

        var offerStatus = (
            applicationGR.getValue('offer_status') || ''
        ).toLowerCase();

        var applicationScore = 0;


        // Highest stage reached
        if (offerStatus == 'accepted') {

            applicationScore = 100;

        } else if (applicationStatus == 'selected') {

            applicationScore = 100;

        } else if (interviewStatus == 'completed') {

            applicationScore = 90;

        } else if (
            applicationStatus == 'shortlisted' ||
            applicationGR.getValue('shortlisted') == '1'
        ) {

            applicationScore = 80;

        } else if (assessmentStatus == 'passed') {

            applicationScore = 70;

        } else if (
            assessmentStatus == 'in_progress' ||
            assessmentStatus == 'in progress'
        ) {

            applicationScore = 60;

        } else if (
            applicationStatus == 'submitted' ||
            applicationStatus == 'under_review' ||
            applicationStatus == 'under review'
        ) {

            applicationScore = 50;

        } else if (applicationStatus == 'pending') {

            applicationScore = 40;

        } else if (applicationStatus == 'rejected') {

            applicationScore = 20;

        } else if (applicationStatus == 'withdrawn') {

            applicationScore = 10;
        }


        applicationTotal += applicationScore;
        applicationCount++;


        // Missed opportunity
        var studentResponse = (
            applicationGR.getValue('student_response') || ''
        ).toLowerCase();

        if (
            studentResponse == 'ignored' ||
            studentResponse == 'not_interested' ||
            studentResponse == 'not interested'
        ) {

            missedOpportunities++;
        }
    }


    // =========================================================
    // 6. TRAINING READINESS
    //
    // Training Score =
    // 60% Attendance + 40% Completion
    //
    // Completed   = 100
    // In Progress = 60
    // Not Started = 0
    // =========================================================

    var trainingGR = new GlideRecord(
        'x_snc_campus360_training_enrollment'
    );

    trainingGR.addQuery('student', studentId);
    trainingGR.query();

    while (trainingGR.next()) {

        var attendance = parseFloat(
            trainingGR.getValue('attendance')
        );

        if (!isNaN(attendance)) {

            trainingAttendanceTotal += attendance;

            var completionStatus = (
                trainingGR.getValue('completion_status') || ''
            ).toLowerCase();

            var completionScore = 0;

            if (completionStatus == 'completed') {

                completionScore = 100;

            } else if (
                completionStatus == 'in_progress' ||
                completionStatus == 'in progress'
            ) {

                completionScore = 60;

            } else if (
                completionStatus == 'not_started' ||
                completionStatus == 'not started'
            ) {

                completionScore = 0;
            }

            trainingCompletionTotal += completionScore;
            trainingCount++;
        }
    }


    // =========================================================
    // 7. MOCK INTERVIEW PARTICIPATION
    //
    // Completed / Selected / Rejected = participated
    // =========================================================

    var mockGR = new GlideRecord(
        'x_snc_campus360_mock_interview'
    );

    mockGR.addQuery('student', studentId);
    mockGR.query();

    while (mockGR.next()) {

        mockInterviewCount++;

        var mockStatus = (
            mockGR.getValue('interview_status') || ''
        ).toLowerCase();

        if (
            mockStatus == 'completed' ||
            mockStatus == 'selected' ||
            mockStatus == 'rejected'
        ) {

            completedInterviewCount++;
        }
    }


    // =========================================================
    // 8. CALCULATE COMPONENT SCORES
    // =========================================================

    var interviewScore = null;

    if (interviewCount > 0) {
        interviewScore =
            interviewTotal / interviewCount;
    }


    var skillScore = null;

    if (skillCount > 0) {
        skillScore =
            skillTotal / skillCount;
    }


    var assessmentScore = null;

    if (assessmentCount > 0) {
        assessmentScore =
            assessmentTotal / assessmentCount;
    }


    var applicationScore = null;

    if (applicationCount > 0) {
        applicationScore =
            applicationTotal / applicationCount;
    }


    var trainingScore = null;

    if (trainingCount > 0) {

        var averageAttendance =
            trainingAttendanceTotal / trainingCount;

        var averageCompletion =
            trainingCompletionTotal / trainingCount;

        trainingScore =
            (averageAttendance * 0.60) +
            (averageCompletion * 0.40);
    }


    // =========================================================
    // 9. FINAL READINESS SCORE
    //
    // Interview    = 40%
    // Skills       = 20%
    // Assessment   = 15%
    // Application  = 15%
    // Training     = 10%
    //
    // Missing components are excluded and weights
    // are automatically renormalized.
    // =========================================================

    var weightedTotal = 0;
    var weightTotal = 0;


    if (interviewScore !== null) {

        weightedTotal +=
            interviewScore * 0.40;

        weightTotal += 0.40;
    }


    if (skillScore !== null) {

        weightedTotal +=
            skillScore * 0.20;

        weightTotal += 0.20;
    }


    if (assessmentScore !== null) {

        weightedTotal +=
            assessmentScore * 0.15;

        weightTotal += 0.15;
    }


    if (applicationScore !== null) {

        weightedTotal +=
            applicationScore * 0.15;

        weightTotal += 0.15;
    }


    if (trainingScore !== null) {

        weightedTotal +=
            trainingScore * 0.10;

        weightTotal += 0.10;
    }


    var readinessScore = 0;

    if (weightTotal > 0) {

        readinessScore =
            Math.round(
                weightedTotal / weightTotal
            );
    }


    // =========================================================
    // 10. RISK LEVEL
    //
    // 80-100 = Low
    // 65-79  = Medium
    // 50-64  = High
    // 0-49   = Critical
    // =========================================================

    var riskLevel = 'Critical';

    if (readinessScore >= 80) {

        riskLevel = 'Low';

    } else if (readinessScore >= 65) {

        riskLevel = 'Medium';

    } else if (readinessScore >= 50) {

        riskLevel = 'High';
    }


    // =========================================================
    // 11. PARTICIPATION SCORE
    //
    // Training Attendance = 60%
    // Mock Interview      = 40%
    //
    // Missing components are excluded.
    // =========================================================

    var participationTotal = 0;
    var participationWeight = 0;


    if (trainingCount > 0) {

        var averageTrainingAttendance =
            trainingAttendanceTotal / trainingCount;

        participationTotal +=
            averageTrainingAttendance * 0.60;

        participationWeight += 0.60;
    }


    if (mockInterviewCount > 0) {

        var interviewParticipation =
            (
                completedInterviewCount /
                mockInterviewCount
            ) * 100;

        participationTotal +=
            interviewParticipation * 0.40;

        participationWeight += 0.40;
    }


    var participationScore = 0;

    if (participationWeight > 0) {

        participationScore =
            Math.round(
                participationTotal /
                participationWeight
            );
    }


    // =========================================================
    // 12. RETURN OUTPUTS TO THE FLOW
    // =========================================================

    outputs.readiness_score =
        readinessScore;

    outputs.risk_level =
        riskLevel;

    outputs.participation_score =
        participationScore;

    outputs.missed_opportunities =
        missedOpportunities;
    outputs.student = inputs.student;


})(inputs, outputs);

